#!/usr/bin/env bash
# Question 9: Back up etcd. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -f "${Q9_BACKUP}"
mkdir -p "$(dirname "${Q9_BACKUP}")"
kubectl -n default create configmap "${Q9_MARKER}" --from-literal=created="$(date -Is)" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
rm -f "${Q9_STATUS_FILE}"
